-- Carga dos produtos das farmácias (missão farmacias-2026-11-11). Gerado por gerar_carga_final.mjs.
-- Correr só DEPOIS das migrações 01 (lista de permissão) e 02 (colunas is_medicine/preco_provisorio).
do $$ begin
  if not exists (select 1 from information_schema.columns where table_name='products' and column_name='preco_provisorio')
     or not exists (select 1 from pg_proc where proname='lojas_escondidas_para_mim') then
    raise exception 'Faltam as migrações 01/02 das farmácias: não carregar produtos antes do filtro de visibilidade.';
  end if;
end $$;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (id) do nothing;
