('fse-4611686018581470364', 'farmacia-se-guarda', 'Cegrinaso MG, 200 mg + 30 mg Blister 24 Unidade(s) Comp revest', null, 'Cegrinaso tem ação analgésica, antipirética (diminuição da febre) e descongestionante. Está indicado no tratamento dos sintomas da congestão nasal associada a rinite/sinusite aguda com suspeita de origem viral, dor de cabeça e/ou febre. Está indicado em adultos e adolescentes com idade igual ou superior a 15 anos.', 'Constipação, gripe e alergias', 11.14, 9.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581470364.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 2, '2026-11-11', true, true),
('fse-4611686018581469590', 'farmacia-se-guarda', 'Ilvico, 250/3/10/36 mg x 20 comp rev', null, 'Ilvico está indicado no tratamento dos sintomas das constipações e gripes tais como febre, dor de cabeça, dores dos membros, processos catarrais e congestão nasal.', 'Constipação, gripe e alergias', 10.02, 8.59, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469590.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 3, '2026-11-11', true, true),
('fse-4611686018581470079', 'farmacia-se-guarda', 'Griponal 4 mg + 500 mg Comprimido Efervescente - X 20 Und(s)', null, 'Griponal tem uma ação analgésica, antipirética e anti-histamínica, sendo indicado no tratamento dos sintomas associados a estados gripais e constipações. Indicado em adultos e crianças com idade superior a 12 anos.', 'Constipação, gripe e alergias', 13.22, 11.33, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581470079.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', true, true),
('fse-4611686018581471616', 'farmacia-se-guarda', 'Cêgripe, 1/500 mg x 20 comp', null, 'Cêgripe tem ação analgésica, antipirética (diminuição da febre) e descongestionante. Está indicado no tratamento dos sintomas gripais e constipações.', 'Constipação, gripe e alergias', 11.14, 9.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581471616.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', true, true),
('fse-4611686018581469753', 'farmacia-se-guarda', 'Aspirina C, 400/240 mg x 10 comp eferv', null, null, 'Constipação, gripe e alergias', 7.50, 6.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469753.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', true, true),
('fse-4611686018581469630', 'farmacia-se-guarda', 'Sinutab II, 500/30 mg x 20 comp', null, 'Sinutab II tem ação analésica, antipirética (diminui a febre) e descongestionante. Está indicado no tratamento a curto prazo da congestão nasal e dos seios perinasais associada aos sintomas de constipação e gripe, como dor moderada, dor de cabeça e/ou febre. Indicado em adultos e adolescentes a partir dos 15 anos de idade.', 'Constipação, gripe e alergias', 10.81, 9.27, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469630.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', true, true),
('fse-4611686018581469586', 'farmacia-se-guarda', 'Neo-Sinefrina, 5 mg/mL-15 mL x 1 sol nasal conta-gotas', null, 'Neo-Sinefrina é um descongestionante indicado no alívio rápido da congestão nasal (nariz entupido), normalmente associada à gripe, constipação, sinusite e rinite infeciosa ou alérgica.', 'Constipação, gripe e alergias', 10.64, 9.12, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469586.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', true, true),
('fse-4611686018581469581', 'farmacia-se-guarda', 'Neo-Sinefrina, 2,5 mg/mL-15 mL x 1 sol nasal conta-gotas', null, 'Neo-Sinefrina é um descongestionante indicado no alívio rápido da congestão nasal (nariz entupido), normalmente associada à gripe, constipação, sinusite e rinite infeciosa ou alérgica.', 'Constipação, gripe e alergias', 11.82, 10.13, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469581.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', true, true),
('fse-4611686018581469876', 'farmacia-se-guarda', 'Vibrocil Actilong Mentol, 1 mg/mL-10 mL x 1 sol inal neb mL', null, 'Vibrocil Actilong Mentol é indicado para o alívio devido a constipações, febre dos fenos ou rinites e sinusites. Pode ser usado como adjuvante no descongestionamento da mucosa rinofaríngea.', 'Constipação, gripe e alergias', 11.42, 9.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469876.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 10, '2026-11-11', true, true),
('fse-4611686018581469569', 'farmacia-se-guarda', 'Vibrocil (15 mL), 0,25/2,5 mg/mL x 1 sol pulv nasal', null, 'Vibrocil é um descongestionante indicado no tratamento de sintomas de estados gripais e constipações, nomeadamente congestão nasal (nariz entupido) e corrimento nasal.', 'Constipação, gripe e alergias', 10.30, 8.83, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469569.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 11, '2026-11-11', true, true),
('fse-4611686018581469855', 'farmacia-se-guarda', 'Vibrocil ActilongProtect, 1/50 mg/mL-15mL x 1 sol pulv nasal', null, 'Vibrocil ActilongProtect é indicado para reduzir o inchaço da mucosa nasal na rinite e para o alívio sintomático da mesma. Pode ser usado para o tratamento da obstrução da respiração nasal após cirurgia ao nariz.', 'Constipação, gripe e alergias', 11.42, 9.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469855.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 12, '2026-11-11', true, true),
('fse-4611686018581470092', 'farmacia-se-guarda', 'Nasorhinathiol 0.5 Mg/ml Gotas Nasais, Solução - 15ml', null, 'Nasorhinathiol é um descongestionante que ajuda no alívio da congestão nasal, em situações de rinorreia (corrimento nasal), estados gripais e constipações. Indicado para adultos e crianças com mais de 6 anos.', 'Constipação, gripe e alergias', 12.04, 10.32, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581470092.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', true, true),
('fse-4611686018581469671', 'farmacia-se-guarda', 'Vibrocil Actilong, 0,5 mg/mL-10 mL x 1 sol nasal conta-gotas', null, 'Vibrocil Actilong é um descongestionante nasal para crianças a partir de 1 ano de idade. Com componentes hidratantes, é ideal para o nariz seco e irritado, proporcionando um alívio rápido e até 12 horas.', 'Constipação, gripe e alergias', 10.86, 9.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469671.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 14, '2026-11-11', true, true),
('fse-4611686018581469565', 'farmacia-se-guarda', 'Vibrocil (15 mL), 0,25/2,5 mg/mL x 1 sol nasal conta-gotas', null, 'Vibrocil é um descongestionante indicado no tratamento de sintomas de estados gripais e constipações, nomeadamente corrimento e congestão nasal (nariz entupido).', 'Constipação, gripe e alergias', 9.97, 8.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469565.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 15, '2026-11-11', true, true),
('fse-4611686018581469869', 'farmacia-se-guarda', 'Nasex Duo , 1 mg/ml + 50 mg/ml Frasco 10 ml Sol pulv nasal', null, 'Nasex Duo é indicado para reduzir o inchaço da mucosa nasal na rinite e para o alívio sintomático da mesma. Pode ser usado para o tratamento da obstrução da respiração nasal após cirurgia ao nariz.', 'Constipação, gripe e alergias', 11.37, 9.75, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469869.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 16, '2026-11-11', true, true),
('fse-4611686018581469812', 'farmacia-se-guarda', 'Nasexilo, 1 mg/mL-10 mL x 1 sol pulv nasal', null, 'Actifed descongestionante é uma solução para pulverização nasal para ação local no nariz entupido. Recomendado para adultos e crianças a partir dos 12 anos. Não deve ter um uso prolongado.', 'Constipação, gripe e alergias', 10.75, 9.21, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581469812.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 17, '2026-11-11', true, true),
