values
('fse-4611686018581474513', 'farmacia-se-guarda', 'URIAGE BEBE 1º EAU 500ML', null, 'Uriage Bebé 1ª Água de Limpeza é um concentrado em Água Termal de Uriage, enriquecido com ativos hidratantes e suavizantes que deixam a pele macia e delicadamente perfumada. A sua base lavante suave elimina todas as impurezas do rosto, corpo e rabinho do bebé, sem necessidade de enxaguamento. A presença de glicerina e aloé vera na sua formulação amaciam e hidratam a pele.', 'Bebé e mamã', 21.50, 18.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474513.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', false, true),
('fse-4611686018581474657', 'farmacia-se-guarda', 'URIAGE BEBE 1ºCR LAVANTE 500ML', null, 'Uriage Bebé 1º Creme Lavante limpa em suavidade e preserva o filme hidrolipídico. A sua fórmula enriquecida com o complexo natural [Água Termal de Uriage + Edelweiss Biológico] e Manteiga de Karité deixa a pele suave e hidratada. Com elevada naturalidade e um perfume agradável, a sua base lavante cremosa, sem sabão e com pH fisiológico, elimina todas as impurezas com suavidade.', 'Bebé e mamã', 21.90, 18.77, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474657.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', false, true),
('fse-4611686018581483376', 'farmacia-se-guarda', 'URIAGE BEBE 1º SENTEUR 50ML', null, 'Uriage Bébé 1ª Água Perfumada é uma água com um perfume fresco e delicado. Sem álcool e enriquecida com o complexo natural [Água Termal de Uriage + Edelweiss Biológico], a 1ª Água Perfumada respeita perfeitamente a pele delicada de todos os bebés e crianças.', 'Bebé e mamã', 13.72, 11.76, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483376.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', false, true),
('fse-4611686018581474719', 'farmacia-se-guarda', 'URIAGE BEBE 1º EAU 1L', null, 'Uriage Bebé 1ª Água de Limpeza é um concentrado em Água Termal de Uriage, enriquecido com ativos hidratantes e suavizantes que deixam a pele macia e delicadamente perfumada. A sua base lavante suave elimina todas as impurezas do rosto, corpo e rabinho do bebé, sem necessidade de enxaguamento. A presença de glicerina e aloé vera na sua formulação amaciam e hidratam a pele.', 'Bebé e mamã', 31.36, 26.88, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474719.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', false, true),
('fse-4611686018581475232', 'farmacia-se-guarda', 'URIAGE BEBE 1ºLINIMENT OLEOTHERM500ML', null, 'Uriage Bebé 1º Linimento Óleotermal limpa e elimina com suavidade as impurezas. Ajuda a reduzir a vermelhidão e a prevenir o seu aparecimento. É enriquecido com Água Termal de Uriage naturalmente calmante (30%), que promove o conforto e a hidratação desde a primeira aplicação, e com Óleo de Girassol, Óleo de Linhaça e Óleo de Limnanthes Alba, que formam um filme protetor na superfície da pele para proteger o rabinho do bebé.', 'Bebé e mamã', 16.41, 14.07, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581475232.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', false, true),
