values
('fse-4611686018581483652', 'farmacia-se-guarda', 'URIAGE AGE LIFT CUIDADO CONT OLHOS 15ML', null, 'Uriage Age Lift Cuidado Contorno de Olhos é formulado com retinol e ácido hialurónico, que ajudam a reduzir a aparência das rugas e atuam na perda de firmeza e tonicidade do contorno dos olhos. Possui, ainda, ingredientes descongestionantes que atenuam papos e olheiras, proporcionando um olhar mais descansado. Alisa e hidrata a pele, e protege-a das agressões diárias (luz azul, raios UV, poluição, stress e fadiga). Adequado para todos os tipos de pele, mesmo a mais sensível.', 'Dermocosmética', 33.04, 28.32, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483652.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 79, '2026-11-11', false, true),
('fse-4611686018581474605', 'farmacia-se-guarda', 'VICHY NEOVADIOL GF CONT LAB OLHOS 15ML', null, null, 'Dermocosmética', 34.27, 29.37, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474605.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 80, '2026-11-11', false, true),
('fse-4611686018581481648', 'farmacia-se-guarda', 'VICHY LIFTACTIV SUP OLHOS 15ML', null, 'Vichy Liftactiv Supreme Olhos é indicado para mulheres a partir dos 40 anos que procuram uma correção integral do olhar. Atenua as rugas, refirma as pálpebras e atenuas os papos e olheiras. Tem propriedades reparadoras e apaziguantes, para ajudar a fortalecer o olhar:. - Rhamnose, açúcar vegetal 100% natural, simultaneamente apaziguante e antienvelhecimento capaz de estimular a pele de forma a atenuar as rugas e devolver firmeza à pele;. - Cafeína, favorece a microcirculação cutânea e ajuda a reduzir as olheiras;. - Escina (extracto de castanheiro da Índia), descongestiona e apazigua. Sem perfume. Hipoalergénico. Testado oftalmo e dermatologicamente.', 'Dermocosmética', 33.60, 28.80, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481648.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 81, '2026-11-11', false, true),
('fse-4611686018581475230', 'farmacia-se-guarda', 'LIERAC LIFT INTEG SERUM LIFT OHOS15ML', null, 'Lift Integral Cuidado Lift dos Olhos contém extratos de caju devient mogno e de tulipa alisadores. Corrige as rugas de relaxamento e tem uma ação de lifting nas pálpebras. Contém uma textura de gel. Sem perfume.', 'Dermocosmética', 43.68, 37.44, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581475230.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 82, '2026-11-11', false, true),
('fse-4611686018581481664', 'farmacia-se-guarda', 'NEUTROGENA HYDRO BOOST GEL CR OLH FAD 15ML', null, null, 'Dermocosmética', 19.04, 16.32, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481664.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 83, '2026-11-11', false, true),
('fse-4611686018581471727', 'farmacia-se-guarda', 'MARTIDERM EXPRESS CONTORNO OLHOS/LAB 15ML', null, 'Martiderm Expression Creme Olhos/Lábios ajuda a cuidar e prevenir as rugas de expressão. Tem efeito hidratante, de preenchimento e redensifica a pele. Indicado para todos os tipos de pele. Sem parabenos.', 'Dermocosmética', 52.25, 44.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581471727.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 84, '2026-11-11', false, true),
('fse-4611686018581475383', 'farmacia-se-guarda', 'CERAVE SA CR LIMP RUGOSIDADE 236ML', null, 'Cerave SA Creme Limpeza Antirugosidade é formulado para limpar suavemente e esfoliar a pele seca, áspera e irregular sem alterar a barreira cutânea protetora da pele. O ácido salicílico remove impurezas e oleosidade enquanto esfolia suavemente. Possui 3 ceramidas essenciais que ajudam a manter a barreira natural da pele. Adequado para pele sensível. Sem perfume. Hipoalergénico.', 'Dermocosmética', 15.34, 13.15, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581475383.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 85, '2026-11-11', false, true),
('fse-4611686018581483390', 'farmacia-se-guarda', 'CERAVE CLEANSER HYD LIMP ROST/CORPO 473ML', null, 'CeraVe Creme de Limpeza Hidratante, indicado para higiene diária, composto por 3 ceramidas essenciais, que ajudam a reparar e restaurar a barreira protetora da pele, e por ácido hialurónico, que remove suavemente a sujidade da pele e aumenta a hidratação. Creme para a pele normal a seca, que remove as impurezas, a gordura e maquilhagem sem deixar a pele esticada ou seca.', 'Dermocosmética', 16.02, 13.73, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483390.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 86, '2026-11-11', false, true),
('fse-4611686018581483391', 'farmacia-se-guarda', 'CERAVE CLEANSER ESPUMA LIMP FACIAL 473ML', null, 'CeraVe Gel Espuma de Limpeza apresenta na sua composição 3 ceramidas essenciais que ajudam a reparar e restaurar a barreira protetora da pele. Com niacinamida e ácido hialurónico permite acalmar a pele. Tem uma ação espumosa que ajuda a limpar e refrescar em profundidade. Sem perfume. Não comedogénico.', 'Dermocosmética', 16.69, 14.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483391.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 87, '2026-11-11', false, true),
('fse-4611686018581478525', 'farmacia-se-guarda', 'CERAVE BLEMISH GEL LIMP IMPERF 236ML', null, null, 'Dermocosmética', 16.18, 13.87, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581478525.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 88, '2026-11-11', false, true),
('fse-4611686018581478356', 'farmacia-se-guarda', 'CERAVE CLEANSER HYD LIMP FACIAL 236ML', null, 'CeraVe Creme de Limpeza Hidratante Facial apresenta na sua composição 3 ceramidas essenciais que ajudam a reparar e restaurar a barreira protetora da pele. As ceramidas em conjunto com o ácido hialurónico, removem suavemente a sujidade da pele e aumentam a hidratação. Adaptado para crianças e adultos. Sem perfume. Não comedogénico.', 'Dermocosmética', 10.53, 9.03, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581478356.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 89, '2026-11-11', false, true),
('fse-4611686018581483388', 'farmacia-se-guarda', 'CERAVE CLEANSER ESPUMA LIMP FACIAL 236ML', null, 'CeraVe Gel Espuma de Limpeza apresenta na sua composição 3 ceramidas essenciais que ajudam a reparar e restaurar a barreira protetora da pele. Com niacinamida e ácido hialurónico permite acalmar a pele. Tem uma ação espumosa que ajuda a limpar e refrescar em profundidade. Sem perfume. Não comedogénico.', 'Dermocosmética', 12.21, 10.47, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483388.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 90, '2026-11-11', false, true),
('fse-4611686018581472693', 'farmacia-se-guarda', 'ISDINCEUT ESSENTIAL CLEANSING 200ML', null, null, 'Dermocosmética', 40.43, 34.65, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581472693.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 91, '2026-11-11', false, true),
('fse-4611686018581474410', 'farmacia-se-guarda', 'ISDIN ACNIBEN GEL LIMP 400ML', null, null, 'Dermocosmética', 23.69, 20.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474410.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 92, '2026-11-11', false, true),
('fse-4611686018581474409', 'farmacia-se-guarda', 'ISDIN ACNIBEN ESPUMA LIMP 150ML', null, 'ISDIN Teen Skin Acniben 1 Espuma de Limpeza Purificante elimina o excesso de sebo e purifica a pele, ajudando a minimizar as imperfeições e vermelhidões cutâneas com suavidade. Sebo regulador graças à zincamida e agentes calmoactive. Hidrata graças à trimetilglicina e tensioativos syndet. Ação comedolítica graças à sua formulação com ácido láctico e arginina. Não deixa resíduos de oleosidade. Hipoalergénico. Testado dermatologicamente.', 'Dermocosmética', 16.86, 14.45, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474409.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 93, '2026-11-11', false, true),
('fse-4611686018581483700', 'farmacia-se-guarda', 'LRPOSAY DESMAQ ESPUMA MIC 150ML', null, 'La Roche-Posay Espuma de Água Micelar limpa gentilmente as impurezas da pele e remove a maquilhagem. Apazigua ainda a pele e respeita o seu equilíbrio fisiológico, graças a uma fórmula enriquecida com polímeros derivados de limpeza médica de olhos. Ideal para a pele sensível. Sem sabão, álcool e corantes.', 'Dermocosmética', 19.66, 16.85, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483700.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 94, '2026-11-11', false, true),
('fse-4611686018581483616', 'farmacia-se-guarda', 'LRPOSAY MELA B3 CLEANSER GEL 200ML', null, null, 'Dermocosmética', 23.91, 20.49, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483616.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 95, '2026-11-11', false, true),
('fse-4611686018581483473', 'farmacia-se-guarda', 'LRPOSAY EFFACLAR GEL PURIF 400ML', null, 'Effaclar Gel Purificante ajuda a reduzir as imperfeições severas, incluindo as marcas. Ação antirreaparecimento. Ajuda a eliminar as células mortas sem fricção. Efeito matificante. Deixa a pele macia, limpa e fresca. Indicado para rosto e corpo. Textura não colante. Testado em pele oleosa e com tendência acneica. Hipoalergénico.', 'Dermocosmética', 29.40, 25.20, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483473.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 96, '2026-11-11', false, true),
('fse-4611686018581474555', 'farmacia-se-guarda', 'LRPOSAY TOLERIANE DERMO NETTOYANT 400ML', null, 'Toleriane Fluido Dermo-Nettoyant tem uma textura fluida, enriquecida com Glicerina hidratante, para minimizar riscos de intolerâncias. Tolerância alta. Sem perfume, tensioactivos e conservantes.', 'Dermocosmética', 27.55, 23.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474555.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 97, '2026-11-11', false, true),
('fse-4611686018581474456', 'farmacia-se-guarda', 'MUSTELA PN AGUA LIMPEZA BEBE500ML PRESP', null, null, 'Dermocosmética', 14.45, 12.39, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474456.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 98, '2026-11-11', false, true),
('fse-4611686018581470168', 'farmacia-se-guarda', 'LRPOSAY EFFACLAR LOCAO ADSTRING 200ML', null, 'Effaclar Loção Adstringente Microesfoliante ajuda a reduzir o tamanho dos poros e a combater a sua obstrução, graças à associação de ativos seborreguladores, purificadores com o LHA microesfoliante. Progressivamente a superfície da pele torna-se mais suave e uniforme. Os poros ficam mais pequenos, e a pele com um aspeto mais homogéneo.', 'Dermocosmética', 21.50, 18.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581470168.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 99, '2026-11-11', false, true),
('fse-4611686018581478471', 'farmacia-se-guarda', 'URIAGE EAU THERM ESSENSE D´EAU ECLAT 100ML', null, null, 'Dermocosmética', 22.12, 18.96, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581478471.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 100, '2026-11-11', false, true),
('fse-4611686018581478575', 'farmacia-se-guarda', 'URIAGE HYSEAC TONIC PURIFIC 250ML', null, null, 'Dermocosmética', 18.42, 15.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581478575.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 101, '2026-11-11', false, true),
('fse-4611686018581483520', 'farmacia-se-guarda', 'AVENE TOLERANCE LOC 200ML', null, 'Avène Tolérance Loção de Limpeza Gelificada limpa e remove suavemente a maquilhagem e as impurezas acumuladas durante o dia, sem irritar demasiado a pele ou sem secá-la. Possui uma textura suave em gel. Sem perfume.', 'Dermocosmética', 23.18, 19.87, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581483520.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 102, '2026-11-11', false, true),
('fse-4611686018581481589', 'farmacia-se-guarda', 'AVENE AG TERMAL LOCAO TONICA SUAVE 200ML', null, 'Avène Loção Suavizante deve ser utilizado como o passo final do processo de limpeza. É enriquecida com salicilatos que protegem a pele diariamente com toda a suavidade. Especialmente indicado para a pele sensível e seca. Sem álcool. Hipoalergénico. Não comedogénico.', 'Dermocosmética', 19.10, 16.37, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481589.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 103, '2026-11-11', false, true),
