('fse-4611686018581475396', 'farmacia-se-guarda', 'PAPILLON PURE MINT CH CAB/BAR/CORP100ML', null, null, 'Homem', 7.73, 6.63, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581475396.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', false, true),
('fse-4611686018581481673', 'farmacia-se-guarda', 'DERCOS AMINEXIL CLINICAL HOM AMPX21', null, 'Vichy Dercos Aminexil Clinical 5 monodoses homem contém uma associação exclusiva de Aminexil, molécula antiqueda de referência com eficácia clinicamente comprovada, e 5 ativos, numa fórmula para uma ação completa. Os cabelos recuperam a resistência e a força. Textura levemente gelificada, não gordurosa, não cola e não oleosa. Não deixa resíduos visíveis. Fácil aplicação. Hipoalergénico. Testado dermatologicamente.', 'Homem', 72.80, 62.40, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481673.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 14, '2026-11-11', false, true),
