('fse-4611686018581481487', 'farmacia-se-guarda', 'VICHY FLEXITEINT 25 ANTIRUGAS 30ML', null, null, 'Maquilhagem e perfumes', 38.53, 33.03, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481487.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 19, '2026-11-11', false, true),
('fse-4611686018581481488', 'farmacia-se-guarda', 'VICHY FLEXITEINT 45 ANTIRUGAS 30ML', null, 'Vichy Liftactiv Flexiteint base antirrugas tem uma textura de silicone tensor para um efeito lifting radiante durante todo o dia, sem rigidez dos traços. Formulada com collagyl, um constituinte ativo antirrugas, que preenche as rugas, deixando a pele mais lisa e restituindo o seu aspeto inicial. Apresenta um fator de proteção solar médio (SPF 20). A sua textura fluída confere um efeito matificante de longa duração e uma melhor fixação da maquilhagem. Não comedogénico.', 'Maquilhagem e perfumes', 38.53, 33.03, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481488.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 20, '2026-11-11', false, true),
