('fse-4611686018581481476', 'farmacia-se-guarda', 'AVENE COUVRANCE BASE FL PORCEL 30ML', null, null, 'Maquilhagem e perfumes', 25.48, 21.84, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581481476.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 22, '2026-11-11', false, true),
('fse-4611686018581474872', 'farmacia-se-guarda', 'SENSIBIO BIODERMA AR BB CR 40ML', null, 'Sensibio AR BB Creme é um cuidado de rosto indicado na vermelhidão intensa e transitória, provocada por vários fatores como o stress e alterações climáticas e na vermelhidão permanente (couperose, rosácea). Previne a vermelhidão. Uniformiza, ilumina e alisa a pele para um toque aveludado. Acalma, hidrata e protege dos raios UV (FPS30+). A cor natural clara adequa-se à maioria dos tons de pele. Ligeiramente perfumado. Hipoalergénico. Não comedogénico.', 'Maquilhagem e perfumes', 33.15, 28.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-se-guarda/fse-4611686018581474872.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 23, '2026-11-11', false, true),
