values
('fte-4611686018581477187', 'farmacia-teixeira-guarda', 'Bebegel, 3830 mg/4,5 g x 6 gel rect bisnaga', null, 'Bebegel é um laxante indicado em situações de obstipação. Pode ser também utilizado para preparação do tubo digestivo para intervenções cirúrgicas ou para exames de diagnóstico. Pode ser utilizado por adultos, bebés e crianças, grávidas e mulheres em período de amamentação.', 'Medicamentos sem receita', 8.74, 7.49, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477187.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 1, '2026-11-11', true, true),
('fte-4611686018581470270', 'farmacia-teixeira-guarda', 'Imodium Rapid, 2 mg x 10 comp orodisp', null, 'Imodium Rapid está indicado no tratamento da diarreia. Torna as fezes sólidas e menos frequentes e pode ser utilizado tanto na diarreia repentina (aguda) como na diarreia de longa duração (crónica).', 'Medicamentos sem receita', 11.09, 9.51, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470270.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 2, '2026-11-11', true, true),
('fte-4611686018581470265', 'farmacia-teixeira-guarda', 'Dagragel (6,5 g), 0,078/5,532 g x 6 gel rect bisnaga', null, 'Dagragel é um laxante indicado no tratamento da obstipação (prisão de ventre). Pode ser utilizado na obstipação durante a gravidez e na obstipação associada ao parto e cirurgia (uso pré e pós-operatório). Também indicado na preparação para endoscopias.', 'Medicamentos sem receita', 8.74, 7.49, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470265.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 3, '2026-11-11', true, true),
('fte-4611686018581470117', 'farmacia-teixeira-guarda', 'Microlax, 450/45 mg/5 mL x 6 enema sol tubo', null, 'Microlax tem uma ação laxante, estando indicado no tratamento da obstipação (prisão de ventre). Pode ser utilizado na obstipação durante a gravidez e na obstipação associada ao parto e cirurgia (uso pré e pós-operatório). Também indicado na preparação para endoscopias.', 'Medicamentos sem receita', 9.41, 8.07, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470117.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', true, true),
('fte-4611686018581470469', 'farmacia-teixeira-guarda', 'Dulcolax, 5 mg x 40 comp rev', null, 'Dulcolax tem ação laxante e está indicado para o alívio da obstipação (prisão de ventre), através da estimulação da defecação, redução do tempo de trânsito e amolecimento das fezes. Pode ser utilizado para preparação de cirurgias (uso pré e pós-operatório) e antes da realização de exames (endoscopia, raio-x).', 'Medicamentos sem receita', 17.02, 14.59, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470469.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', true, true),
('fte-4611686018581470146', 'farmacia-teixeira-guarda', 'Buscopan, 10 mg x 20 comp rev', null, 'Buscopan tem ação espasmolítica sobre a musculatura lisa do aparelho gastrointestinal e das vias biliares e genito-urinárias. Indicado para o alívio de dor ou desconforto abdominal associado a espasmos transitórios e moderados do trato gastrointestinal.', 'Medicamentos sem receita', 7.84, 6.72, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470146.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', true, true),
('fte-4611686018581470759', 'farmacia-teixeira-guarda', 'Buscopan Compositum N 10 mg + 500 mg Comprimido Revestido - X 20 Und(s)', null, 'Buscopan Compositum N tem ação espasmolítica, ação analgésica e ação anti-inflamatória ligeira. Indicado para adultos, no alívio de dor ou desconforto abdominal associado a espasmos transitórios e moderados do trato gastrointestinal e dor menstrual primária.', 'Medicamentos sem receita', 10.64, 9.12, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470759.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', true, true),
('fte-4611686018581470766', 'farmacia-teixeira-guarda', 'Buscopan 10 mg Comprimido Revestido - X 40 Und(s)', null, 'Buscopan tem ação espasmolítica sobre a musculatura lisa do aparelho gastrointestinal e das vias biliares e genito-urinárias. Indicado para o alívio de dor ou desconforto abdominal associado a espasmos transitórios e moderados do trato gastrointestinal.', 'Medicamentos sem receita', 12.99, 11.13, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470766.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', true, true),
('fte-4611686018581470369', 'farmacia-teixeira-guarda', 'Aero-Om, 105 mg/mL-25 mL x 1 emul oral gta', null, 'Aero-Om é um antiflatulento indicado, especialmente em bebés e crianças, na flatulência ( gases), dificuldades de eructação (dificuldade em arrotar) e regurgitação, cólicas e sensação de enfartamento.', 'Medicamentos sem receita', 17.75, 15.21, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470369.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', true, true),
('fte-4611686018581470246', 'farmacia-teixeira-guarda', 'Aero-OM, 125 mg x 60 cáps mole', null, 'Aero-OM Cápsula Mole está indicado para adultos e crianças a partir dos 12 anos. Recomendado para o tratamento dos sintomas desconfortáveis provocados por gases (distensão abdominal, flatulência).', 'Medicamentos sem receita', 31.58, 27.07, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470246.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 10, '2026-11-11', true, true),
('fte-4611686018581470343', 'farmacia-teixeira-guarda', 'Dulcolax, 5 mg x 20 comp rev', null, 'Dulcolax tem ação laxante e está indicado para o alívio da obstipação (prisão de ventre), através da estimulação da defecação, redução do tempo de trânsito e amolecimento das fezes. Pode ser utilizado para preparação de cirurgias (uso pré e pós-operatório) e antes da realização de exames (endoscopia, raio-x).', 'Medicamentos sem receita', 9.30, 7.97, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470343.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 11, '2026-11-11', true, true),
('fte-4611686018581470176', 'farmacia-teixeira-guarda', 'DIORALYTE (SABOR LIMAO) X 20', null, 'Dioralyte (Sabor Limão) é uma associação de sais para re-hidratação oral. Está indicado como tratamento em situações de diarreia aquosa de várias origens, incluindo as gastrenterites, em todos os grupos etários.', 'Medicamentos sem receita', 12.21, 10.47, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470176.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 12, '2026-11-11', true, true),
('fte-4611686018581470797', 'farmacia-teixeira-guarda', 'Maalox Plus 200 mg + 200 mg + 26.25 mg Comprimido para Mastigar - X 40 Und(s)', null, 'Maalox Plus é um medicamento antiácido que contém hidróxidos de alumínio e magnésio que promovem a restauração da peristaltese, eliminando os obstáculos reflexogénicos como a hiperacidez e os estados de irritabilidade. O componente simeticone atua como antiflatulento, pois adsorve gradualmente o gás presente no estômago e no intestino eliminando a distensão dolorosa da parede gástrica e o meteorismo intestinal. Não provoca prisão de ventre nem gases no trato intestinal.', 'Medicamentos sem receita', 11.14, 9.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470797.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', true, true),
('fte-4611686018581470063', 'farmacia-teixeira-guarda', 'Kompensan-S, 340/30 mg x 20 comp mast', null, 'Kompensan-S está indicado no alívio dos sintomas da azia (sensação de queimadura no estômago) e enfartamento devidos à produção excessiva de ácido no estômago. Também está indicado em caso de flatulência (produção excessiva de gases).', 'Medicamentos sem receita', 7.56, 6.48, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470063.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 14, '2026-11-11', true, true),
('fte-4611686018581470784', 'farmacia-teixeira-guarda', 'Gaviscon Duefet Associação Suspensão Oral - X 12 Und(s)', null, 'Gaviscon Duefet encontra-se indicado no alívio da azia e indigestão, que podem ocorrer após as refeições, durante a gravidez ou em doentes com sintomas relacionados com esofagite.', 'Medicamentos sem receita', 12.15, 10.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470784.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 15, '2026-11-11', true, true),
('fte-4611686018581470068', 'farmacia-teixeira-guarda', 'Kompensan-S, 340/30 mg x 60 comp mast', null, 'Kompensan-S está indicado no alívio dos sintomas da azia (sensação de queimadura no estômago) e enfartamento devidos à produção excessiva de ácido no estômago. Também está indicado em caso de flatulência (produção excessiva de gases).', 'Medicamentos sem receita', 15.23, 13.05, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470068.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 16, '2026-11-11', true, true),
