('fte-4611686018581472379', 'farmacia-teixeira-guarda', 'OHROPAX SOFT TAMPOES AURIC ESPUMA X10', null, null, 'Medicamentos sem receita', 9.63, 8.25, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472379.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 21, '2026-11-11', false, true),
('fte-4611686018581472529', 'farmacia-teixeira-guarda', 'OHROPAX TAMPOES AUD ESPUMA MACIA COLOR X8', null, null, 'Medicamentos sem receita', 7.45, 6.39, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472529.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 22, '2026-11-11', false, true),
('fte-4611686018581472649', 'farmacia-teixeira-guarda', 'Gino-canesten 10 Mg/g Creme Vaginal - 50g', null, 'Gino-Canesten é um creme vaginal com ação antifúngica, indicado para Candidíase vaginal recorrente, Infeções dos lábios genitais (vulva) e áreas adjacentes, bem como inflamação da glande e prepúcio do parceiro sexual causadas por leveduras (vulvite por Candida e Candidíase balânica).', 'Medicamentos sem receita', 11.31, 9.69, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472649.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 23, '2026-11-11', true, true),
('fte-4611686018581472650', 'farmacia-teixeira-guarda', 'Gino-canesten 1 500 mg Cápsula Mole Vaginal', null, 'Gino-Canesten 1 é uma cápsula mole vaginal com ação antifúngica, indicada para Candidíase vaginal recorrente.', 'Medicamentos sem receita', 11.31, 9.69, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472650.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 24, '2026-11-11', true, true),
('fte-4611686018581470571', 'farmacia-teixeira-guarda', 'FISIOCREM PATCH ACTIVE X4', null, 'Fisiocrem Patch Active é um adesivo cutâneo para o tratamento de dores musculares e articulares. A sua tecnologia de microcorrentes alivia as dor em lesões articulares e musculares causadas por contusões, pancadas, deslocações, entorses, hematomas, traumatismos, quedas, torcicolos, dores lombares ou cervicais. Composto por uma camada externa com tiras de cobre e zinco e uma camada interna com arnica e harpagófito.', 'Medicamentos sem receita', 14.50, 12.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470571.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 25, '2026-11-11', false, true),
