('fte-4611686018581470106', 'farmacia-teixeira-guarda', 'Neo-Sinefrina, 5 mg/mL-15 mL x 1 sol nasal conta-gotas', null, 'Neo-Sinefrina é um descongestionante indicado no alívio rápido da congestão nasal (nariz entupido), normalmente associada à gripe, constipação, sinusite e rinite infeciosa ou alérgica.', 'Constipação, gripe e alergias', 9.07, 7.77, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470106.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', true, true),
('fte-4611686018581470101', 'farmacia-teixeira-guarda', 'Neo-Sinefrina, 2,5 mg/mL-15 mL x 1 sol nasal conta-gotas', null, 'Neo-Sinefrina é um descongestionante indicado no alívio rápido da congestão nasal (nariz entupido), normalmente associada à gripe, constipação, sinusite e rinite infeciosa ou alérgica.', 'Constipação, gripe e alergias', 10.64, 9.12, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470101.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', true, true),
('fte-4611686018581470544', 'farmacia-teixeira-guarda', 'Vibrocil Actilong Mentol, 1 mg/mL-10 mL x 1 sol inal neb mL', null, 'Vibrocil Actilong Mentol é indicado para o alívio devido a constipações, febre dos fenos ou rinites e sinusites. Pode ser usado como adjuvante no descongestionamento da mucosa rinofaríngea.', 'Constipação, gripe e alergias', 11.42, 9.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470544.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', true, true),
('fte-4611686018581470087', 'farmacia-teixeira-guarda', 'Vibrocil (15 mL), 0,25/2,5 mg/mL x 1 sol pulv nasal', null, 'Vibrocil é um descongestionante indicado no tratamento de sintomas de estados gripais e constipações, nomeadamente congestão nasal (nariz entupido) e corrimento nasal.', 'Constipação, gripe e alergias', 10.86, 9.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470087.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 10, '2026-11-11', true, true),
('fte-4611686018581470509', 'farmacia-teixeira-guarda', 'Vibrocil ActilongProtect, 1/50 mg/mL-15mL x 1 sol pulv nasal', null, 'Vibrocil ActilongProtect é indicado para reduzir o inchaço da mucosa nasal na rinite e para o alívio sintomático da mesma. Pode ser usado para o tratamento da obstrução da respiração nasal após cirurgia ao nariz.', 'Constipação, gripe e alergias', 10.53, 9.03, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470509.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 11, '2026-11-11', true, true),
('fte-4611686018581470228', 'farmacia-teixeira-guarda', 'Vibrocil Actilong, 0,5 mg/mL-10 mL x 1 sol nasal conta-gotas', null, 'Vibrocil Actilong é um descongestionante nasal para crianças a partir de 1 ano de idade. Com componentes hidratantes, é ideal para o nariz seco e irritado, proporcionando um alívio rápido e até 12 horas.', 'Constipação, gripe e alergias', 10.86, 9.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470228.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 12, '2026-11-11', true, true),
('fte-4611686018581470810', 'farmacia-teixeira-guarda', 'Nasorhinathiol 0.5 Mg/ml Gotas Nasais, Solução - 15ml', null, 'Nasorhinathiol é um descongestionante que ajuda no alívio da congestão nasal, em situações de rinorreia (corrimento nasal), estados gripais e constipações. Indicado para adultos e crianças com mais de 6 anos.', 'Constipação, gripe e alergias', 11.82, 10.13, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470810.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', true, true),
('fte-4611686018581470083', 'farmacia-teixeira-guarda', 'Vibrocil (15 mL), 0,25/2,5 mg/mL x 1 sol nasal conta-gotas', null, 'Vibrocil é um descongestionante indicado no tratamento de sintomas de estados gripais e constipações, nomeadamente corrimento e congestão nasal (nariz entupido).', 'Constipação, gripe e alergias', 9.97, 8.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470083.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 14, '2026-11-11', true, true),
('fte-4611686018581470531', 'farmacia-teixeira-guarda', 'Nasex Duo , 1 mg/ml + 50 mg/ml Frasco 10 ml Sol pulv nasal', null, 'Nasex Duo é indicado para reduzir o inchaço da mucosa nasal na rinite e para o alívio sintomático da mesma. Pode ser usado para o tratamento da obstrução da respiração nasal após cirurgia ao nariz.', 'Constipação, gripe e alergias', 11.37, 9.75, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470531.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 15, '2026-11-11', true, true),
