('fte-4611686018581482579', 'farmacia-teixeira-guarda', 'AVENE CICALFATE+ CR 40ML', null, null, 'Primeiros socorros', 16.18, 13.87, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482579.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', false, true),
('fte-4611686018581482580', 'farmacia-teixeira-guarda', 'AVENE CICALFATE+ CR 100ML', null, 'Avène Cicalfate+ Creme é indicado para toda a família, incluindo récem-nascidos. O C+ Restore acelera o processo de reparação epidérmica. O sulfato de cobre e o sulfato de zinco permitem a manutenção de um ambiente adequado à regeneração cutânea. Devido à água terma d'' Àvene ajuda a acalmar a sensação de desconforto da epiderme frágil. Textura cremosa e fácil de espalhar. Pode ser utilizado no rosto e corpo. Para pele sensível e irritada. Sem perfume. Não comedogénico.', 'Primeiros socorros', 26.88, 23.04, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482580.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', false, true),
('fte-4611686018581484183', 'farmacia-teixeira-guarda', 'AVENE CICALFATE+ SPRAY 100ML', null, 'Avène Cicalfate+ Spray ajuda a reparar e acalmar a pele irritada sujeita a maceração. Para bebés, crianças e adultos. Indicado para rosto, corpo e zona da fralda. Os pós absorventes secam rapidamente as irritações superficiais. A combinação de sulfato de cobre e sulfato de zinco limita o risco de proliferação bacteriana, favorecendo a regeneração da pele.', 'Primeiros socorros', 16.35, 14.01, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484183.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', false, true),
('fte-4611686018581471849', 'farmacia-teixeira-guarda', 'Halibut, 150 mg/g-100 g x 1 pda', null, 'Halibut, com ação calmante, cicatrizante e regeneradora dos tecidos. Indicado na dermatite da fralda (assaduras do rabinho), queimaduras superficiais, incluindo queimaduras solares, e na cicatrização de feridas superficiais .', 'Primeiros socorros', 13.83, 11.85, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471849.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 10, '2026-11-11', true, true),
('fte-4611686018581471018', 'farmacia-teixeira-guarda', 'Bepanthene, 50 mg/g-30 g x 1 creme bisnaga', null, 'Bepanthene é um cicatrizante indicado para situações em que a sua pele está lesada ou irritada. Tem um efeito calmante e reparador. Pode usar em situações de agressão externa, tais como feridas e queimaduras. É indicado em situações de dermatite da fralda (assadura).', 'Primeiros socorros', 6.83, 5.85, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471018.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 11, '2026-11-11', true, true),
('fte-4611686018581470960', 'farmacia-teixeira-guarda', 'Biafine, 6,7 mg/g-100 mL x 1 emul bisnaga', null, 'Biafine cria o ambiente húmido ótimo para os processos de cicatrização e regeneração da sua pele.', 'Primeiros socorros', 12.21, 10.47, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470960.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 12, '2026-11-11', true, true),
('fte-4611686018581470748', 'farmacia-teixeira-guarda', 'Betadine 100 Mg/ml Solução Cutânea - 125ml', null, 'Betadine é um desinfetante e antisséptico indicado na desinfeção de feridas e para o tratamento ou prevenção do pé de atleta. Também utilizado na desinfeção da pele e mucosas antes de intervenções cirúrgicas. Pode ser utilizado por adultos e crianças com mais de 1 mês de idade.', 'Primeiros socorros', 9.07, 7.77, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581470748.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', true, true),
('fte-4611686018581482277', 'farmacia-teixeira-guarda', 'DUCRAY DIASEPTYL SPRAY 125ML', null, null, 'Primeiros socorros', 12.32, 10.56, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482277.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 14, '2026-11-11', false, true),
('fte-4611686018581482267', 'farmacia-teixeira-guarda', 'DUCRAY DIASEPTYL SOL 125ML', null, 'Diaseptyl Solução é um antissético cutâneo com elevado poder bactericida, sendo também ativo em fungos e vírus. Pode ser utilizado em bebés, crianças e adultos. Pode ser aplicado em pacientes com pé diabético. Sem álcool - não arde, nem irrita a pele. Sem cor - não colora as lesões. Sem conservantes.', 'Primeiros socorros', 9.52, 8.16, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482267.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 15, '2026-11-11', false, true),
