values
('fte-4611686018581471665', 'farmacia-teixeira-guarda', 'DUREX NATURAL PLU PRESERVATIX12+OF2ªEMB', null, null, 'Saúde sexual e íntima', 10.30, 8.83, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471665.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 3, '2026-11-11', false, true),
('fte-4611686018581471610', 'farmacia-teixeira-guarda', 'DUREX SENSITIVO SUAVE PRESERVATIVO X12', null, 'Durex Sensitivo Suave Preservativo proporciona uma relação sexual prazerosa e segura. São os preservativos mais finos da Durex. São preservativos transparentes, com depósito e concebidos através da tecnologia Easy-On. São fáceis de colocar e adaptam-se anatomicamente, tornando a relação sexual cómoda e agradável. Largura nominal: 56 mm. Testado dermatologicamente. O preservativo é o único método contracetivo que previne o contágio de DST''s (Doenças Sexualmente Transmissíveis).', 'Saúde sexual e íntima', 13.38, 11.47, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471610.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', false, true),
('fte-4611686018581471788', 'farmacia-teixeira-guarda', 'CONTROL FINISSIMO PRESERV ULTRAFEEL X10', null, 'Control Finissimo Preservativos Ultrafeel, com lubrificação standard, à base de silicone, e espessura de 0,044 mm, ajudam a aumentar a sensiblidade e o conforto.', 'Saúde sexual e íntima', 11.14, 9.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471788.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', false, true),
('fte-4611686018581471762', 'farmacia-teixeira-guarda', 'CONTROL NON STOP DL PRESERVAT X12', null, 'Control Non Stop Dots & Lines Preservativos contém benzocaína no seu interior, que retarda a ejaculação masculina, prolongando a relação sexual. À superfície tem pontos e estrias que intensificam o prazer. Largura nominal: 53 mm.', 'Saúde sexual e íntima', 12.15, 10.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471762.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', false, true),
('fte-4611686018581471752', 'farmacia-teixeira-guarda', 'DUREX LOVE SEX ANEL PRAZER', null, null, 'Saúde sexual e íntima', 10.75, 9.21, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471752.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', false, true),
('fte-4611686018581482488', 'farmacia-teixeira-guarda', 'ISDIN WOMAN HIDRAT VULVAR 30G', null, null, 'Saúde sexual e íntima', 18.93, 16.23, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482488.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', false, true),
('fte-4611686018581482248', 'farmacia-teixeira-guarda', 'ISDIN WOMAN HIDRAT VAG 6ML X 12', null, 'Woman ISDIN Hidratante Vaginal é um tratamento não hormonal para a secura vaginal que alivia os sintomas da secura e atrofia vaginais, falta de lubrificação e dor durante as relações sexuais. Permite uma hidratação imediata e prolongada e reduz o prurido e ardor. Aumenta a elasticidade da mucosa vaginal. Concebido com uma fórmula mucoadesiva que origina um filme protetor. Não afeta a integridade dos preservativos. Constituído por 12 aplicadores de uso único. Fórmula testada sob controlo ginecológico.', 'Saúde sexual e íntima', 29.90, 25.63, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482248.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', false, true),
('fte-4611686018581471699', 'farmacia-teixeira-guarda', 'ISDIN WOMAN GEL HIG INTIM 200ML', null, 'Woman ISDIN Higiene Intima Gel é recomendado para as diferentes etapas da vida da mulher e situações nas quais existem alterações como secura vulvar, agressões microbiológicas, comichão ou irritações. Contém Ácido Láctico e o prebiótico Bioecolia que protegem face a agressões microbiológicas e irritações e uma combinação. de ingredientes hidratantes que ajudam a evitar a secura. Não sensibilizante. Testado ginecológica e dermatologicamente.', 'Saúde sexual e íntima', 16.97, 14.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471699.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 10, '2026-11-11', false, true),
('fte-4611686018581482262', 'farmacia-teixeira-guarda', 'LACTACYD INTIMO EMULSAO HIG INTIMA 200ML', null, 'Lactacyd Íntimo Gel é indicado para a higiene diária na mulher, especialmente durante a menstruação e após ter relações sexuais. Contribui para o reforço das defesas naturais, protegendo a flora vaginal. Promove o equilíbrio do pH natural e ajuda a prevenir pequenos problemas e irritações. Permite uma higiene íntima com segurança e proteção durante todo o dia. Emulsão intíma perfumada.', 'Saúde sexual e íntima', 17.30, 14.83, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482262.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 11, '2026-11-11', false, true),
('fte-4611686018581471626', 'farmacia-teixeira-guarda', 'LACTACYD INTIMO GEL HIG INTIMA 400ML', null, 'Lactacyd Íntimo Gel é indicado para a higiene diária na mulher, especialmente durante a menstruação e após ter relações sexuais. Contribui para o reforço das defesas naturais, protegendo a flora vaginal. Promove o equilíbrio do pH natural e ajuda a prevenir pequenos problemas e irritações. Permite uma higiene íntima com segurança e proteção durante todo o dia. Emulsão intíma perfumada.', 'Saúde sexual e íntima', 26.15, 22.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471626.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 12, '2026-11-11', false, true),
('fte-4611686018581471391', 'farmacia-teixeira-guarda', 'Postinor, 1,5 mg x 1 comp', null, 'Postinor é um medicamento utilizado para prevenir o início da gravidez. Este medicamento não tem efeito na mulher já grávida. Não deve ser utilizado como método contracetivo principal.', 'Saúde sexual e íntima', 16.30, 13.97, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471391.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 13, '2026-11-11', true, true),
('fte-4611686018581471240', 'farmacia-teixeira-guarda', 'LRPOSAY EFFACLAR K(+) CR RENOVACAO 40ML', null, null, 'Dermocosmética', 26.66, 22.85, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581471240.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 1, '2026-11-11', false, true),
('fte-4611686018581477635', 'farmacia-teixeira-guarda', 'URIAGE HYSEAC 3-REGUL 40ML', null, 'Uriage Hyséac 3-Regul é um cuidado que favorece a eliminação das borbulhas e os pontos negros graças a um complexo de ativos e à Água Termal de Uriage. Torna o grão de pele significativamente mais liso e fecha os poros. Apresenta uma textura ligeira de rápida absorção. A sua formulação com extrato de Licorice limita o excesso de sebo, muitas vezes responsável pelo aparecimento de novas imperfeições. Hipoalergénico. Não comodogénico. Testado dermatologicamente.', 'Dermocosmética', 18.37, 15.75, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477635.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 2, '2026-11-11', false, true),
('fte-4611686018581477414', 'farmacia-teixeira-guarda', 'AVENE CLEANANCE HYD CR 40ML', null, 'Cleanance Hydra Creme Suavizante hidrata e nutre em profundidade, sendo ideal para acalmar a pele oleosa após um tratamento medicamentoso antiacne. Restaura a barreira protetora da pele e apresenta propriedades suavizantes e dessensibilizantes, acalmando a vermelhidão. Apresenta uma textura untuosa, não gordurosa, que se espalha facilmente. É rapidamente absorvido, restaurando o conforto cutâneo e facilitando o seguimento dos tratamentos medicamentosos antiacne. Hipoalergénico. Não comedogénico.', 'Dermocosmética', 22.74, 19.49, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477414.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 3, '2026-11-11', false, true),
('fte-4611686018581479514', 'farmacia-teixeira-guarda', 'AVENE DERMABSOLU CR DIA PS 40ML', null, 'Dermabsolu Creme Dia Essencial é um cuidado de dia, rico em Água Termal d''Avene, que ajuda a combater os sinais de envelhecimento da pele. Contém polifenóis de baunilha que potenciam a ação do ácido hialurónico na pele. É um creme suave e com um perfume delicado. A pele fica com um aspeto mais preenchido, suave e luminoso. Não comedogénico.', 'Dermocosmética', 56.90, 48.77, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479514.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', false, true),
('fte-4611686018581484195', 'farmacia-teixeira-guarda', 'VICHY NEOVADIOL REPLENISHING 50ML', null, 'Vichy Neovadiol Pós Menopausa Creme de Dia tem uma textura em bálsamo nutritivo e envolvente, com uma combinação de ativos emolientes que atuam nos sinais de envelhecimento causados pela menopausa e que deixam danos, mesmo no pós-menopausa: Proxylane e Extrato de Cassia para aumentar a síntese de procolagénio I e III, para uma pele mais preenchida e firme; Ómegas 3-6-9 para compensar a perda lipídica e nutrir a pele em profundidade; e Niacinamida para uma forte ação antioxidante.', 'Dermocosmética', 47.38, 40.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484195.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', false, true),
('fte-4611686018581479605', 'farmacia-teixeira-guarda', 'VICHY NEOVADIOL REDENSIFYING PS 50ML', null, 'Vichy Neovadiol Cuidado PeriMenopausa Creme Dia Pele Seca ajuda a reativar a elasticidade, densidade e firmeza da pele. Este creme é formulado com uma combinação de Proxylane e Extrato de Cassia para compensar os impactos visíveis das alterações hormonais na pele e Ácido Hialurónico que preenche e melhora a elasticidade da pele. Para pele seca a muito seca e com um efeito redensificante intenso, a pele fica mais firme e nutrida.', 'Dermocosmética', 47.38, 40.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479605.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', false, true),
('fte-4611686018581479604', 'farmacia-teixeira-guarda', 'VICHY NEOVADIOL REPLENISHING NOITE 50ML', null, 'Vichy Neovadiol Pós Menopausa Creme de Noite ajuda a reativar a flacidez, densidade e firmeza da pele. Apresenta uma textura em bálsamo ultra nutritivo e suavizante, com uma combinação de ativos emolientes que atuam nos sinais de envelhecimento causados pela menopausa e que deixam danos, mesmo no pós-menopausa. Este creme é formulado com proxylane e extrato de cassia para aumentar a síntese de procolagénio I e III para uma pele mais preenchida e firme, ómegas 3-6-9 para compensar a perda lipídica e nutrir a pele em profundidade e niacinamida para uma forte ação antioxidante.', 'Dermocosmética', 48.72, 41.76, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479604.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', false, true),
('fte-4611686018581484193', 'farmacia-teixeira-guarda', 'VICHY NEOVADIOL REDENSIFYING NOITE 50ML', null, null, 'Dermocosmética', 37.58, 32.21, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484193.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 8, '2026-11-11', false, true),
('fte-4611686018581477576', 'farmacia-teixeira-guarda', 'VICHY NEOVADIOL CR ROSE PLATINIUM 50ML', null, 'Vichy Neovadiol Creme Rose Platinium é adequado para as mulheres com pele fina, tez baça, com menos densidade e perda de luminosidade e vitalidade. Apresenta na sua constituição Cera de abelha nutritiva e Cálcio fortificante para uma pele mais saudável. A pele recupera força, vitalidade e consistência. Tem uma textura fresca e confortável com um delicado perfume de rosa e uma dose de pigmentos rosa com efeito natural. Hipoalergénico. Testado dermatologicamente.', 'Dermocosmética', 47.38, 40.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477576.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 9, '2026-11-11', false, true),
