('fte-4611686018581484399', 'farmacia-teixeira-guarda', 'CERAVE SERUM HIDRAT AC HIALUR 30ML', null, null, 'Dermocosmética', 22.40, 19.20, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484399.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 81, '2026-11-11', false, true),
('fte-4611686018581479754', 'farmacia-teixeira-guarda', 'AVENE HYALURON ACTIV B3 SERUM 30ML', null, 'Avène Hyaluron Activ B3 Sérum concentrado de preenchimento possui ácido hialurónico e niacinamida que atuam sobre a causa do envelhecimento e promovem a longevidade das células. Promovem, também, um efeito tensor e uma pela mais redendificada e com rugas corrigidas. Adequado para todos os tipos de pele.', 'Dermocosmética', 54.38, 46.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479754.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 82, '2026-11-11', false, true),
('fte-4611686018581482340', 'farmacia-teixeira-guarda', 'VICHY MINERAL 89 CONCENTRADO ROSTO 50ML', null, 'Vichy Minéral 89 Concentrado fortifica a pele, deixando-a mais resistente, radiante e tonificada. Contém 89% de água mineralizante Vichy, que reforça as defesas naturais da pele, e ácido hialurónico de origem natural, com ação preenchedora e hidratante. Sem corantes. Sem perfume e álcool. Hipoalergénico. Testado oftalmológica e dermatologicamente.', 'Dermocosmética', 35.50, 30.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482340.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 83, '2026-11-11', false, true),
