values
('fte-4611686018581484207', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH CENTAUREAS AZUIS 400ML', null, 'Klorane Centáurea Azul Champô destina-se aos cabelos grisalhos ou brancos e loiros graças ao seu teor de cianocentáurea (pigmento vegetal com reflexos azulados), que proporciona reflexos prateados e reduz o amarelecimento. A sua base de lavagem suave respeita a integridade da fibra capilar. Suave e fácil de pentear, o cabelo revela todo o seu brilho. Hipoalergénico. Textura líquida. Aroma a centáurea.', 'Cabelo', 22.01, 18.87, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484207.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 22, '2026-11-11', false, true),
('fte-4611686018581477255', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH CAMOMILA 400ML', null, 'Klorane Capilar Champô de Camomila é adequado a toda a família a partir dos 3 anos. A sua fórmula ultra-suave foi desenvolvida para devolver brilho e luminosidade ao cabelo. Para um desembaraçar macio sem dor. O cabelo fica visivelmente mais leve e suave, dando uma nova vida aos seus reflexos louros.', 'Cabelo', 19.15, 16.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477255.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 23, '2026-11-11', false, true),
('fte-4611686018581477239', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH CAMOMILA 200ML', null, 'Klorane Capilar Champô de Camomila é adequado a toda a família a partir dos 3 anos. A sua fórmula ultra-suave foi desenvolvida para devolver brilho e luminosidade ao cabelo. Para um desembaraçar macio sem dor. O cabelo fica visivelmente mais leve e suave, dando uma nova vida aos seus reflexos louros.', 'Cabelo', 13.33, 11.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477239.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 24, '2026-11-11', false, true),
('fte-4611686018581477254', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH LT AVEIA 400ML', null, 'Klorane Champô de Leite de Aveia é um champô de uso frequente extremamente suave, indicado para toda a família (crianças e adultos). O cabelo fica limpo, hidratado e protegido, readquirindo suavidade e flexibilidade. Apresenta grande tolerância pediátrica. Adequado a crianças a partir dos 3 anos. Sem conservantes. Testado dermatologicamente. .', 'Cabelo', 19.71, 16.89, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477254.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 25, '2026-11-11', false, true),
('fte-4611686018581477463', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH PEONIA 400ML', null, 'Klorane Champô de Peónia apresenta uma textura fluida que devolve frescura ao couro cabeludo irritado. Este champô protetor e suavizante pode ser utilizado sempre que necessário. Fórmula com pH fisiológico que proporciona ao couro cabeludo sensível e irritado uma limpeza com suavidade. Graças ao extrato de Peónia, o couro cabeludo é acalmado ao longo do dia. Com perfume fresco com propriedades relaxantes que alivia o prurido (comichão).', 'Cabelo', 22.79, 19.53, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477463.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 26, '2026-11-11', false, true),
('fte-4611686018581482260', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH LT AVEIA 200ML', null, 'Klorane Champô de Leite de Aveia é um champô de uso frequente extremamente suave, indicado para toda a família (crianças e adultos). O cabelo fica limpo, hidratado e protegido, readquirindo suavidade e flexibilidade. Apresenta grande tolerância pediátrica. Adequado a crianças a partir dos 3 anos. Sem conservantes. Testado dermatologicamente. .', 'Cabelo', 15.01, 12.87, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482260.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 27, '2026-11-11', false, true),
('fte-4611686018581477240', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH CIDRA 200ML', null, null, 'Cabelo', 13.33, 11.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477240.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 28, '2026-11-11', false, true),
('fte-4611686018581484297', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR FIGO INDIA CH 400ML', null, null, 'Cabelo', 19.38, 16.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484297.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 29, '2026-11-11', false, true),
('fte-4611686018581477406', 'farmacia-teixeira-guarda', 'DERCOS ANTICASPA CH CASPA SENSITIVE 200ML', null, 'Vichy Dercos Champô anticaspa para cabelo sensível contém Piroctone olamine para regular a descamação e Bisabolol para acalmar o couro cabeludo. Tem uma dupla eficácia contra a caspa e desconforto no couro cabeludo. O cabelo fica mais saudável, resistente e luminoso. Sem sulfatos e corantes. Testado dermatologicamente.', 'Cabelo', 17.25, 14.79, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477406.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 30, '2026-11-11', false, true),
('fte-4611686018581482357', 'farmacia-teixeira-guarda', 'DERCOS MINERAL CH SUAV 400ML', null, 'Vichy Dercos Champô fortificante mineral suave confere força e brilho aos cabelos, deixando-os visivelmente mais brilhantes e suaves. É enriquecido com Água termal Vichy e minerais, como Ferro, um oxigenante celular, Magnésio, um estimulante da regeneração celular, Silício, um regenerante dos tecidos orgânicos e Cálcio, protetor dos tecidos orgânicos. Sem corantes e silicones. Hipoalergénico. Testado dermatologicamente.', 'Cabelo', 18.87, 16.17, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482357.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 31, '2026-11-11', false, true),
('fte-4611686018581484182', 'farmacia-teixeira-guarda', 'DUCRAY EXTRA DOUX CH USO FREQ 200ML', null, 'Extra-Doux Champô Dermoprotetor é um champô de uso diário que respeita o couro cabeludo, disciplina o cabelo e devolve-lhe vigor, beleza e brilho. Contém uma fórmula biodegradável, elaborada para minimizar o impacto no ambiente. Apresenta um perfume agradável. Não arde nos olhos. Sem silicone.', 'Cabelo', 15.40, 13.20, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484182.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 32, '2026-11-11', false, true),
('fte-4611686018581484121', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR CH SECO ORTIGA BR 50ML', null, null, 'Cabelo', 5.99, 5.13, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484121.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 33, '2026-11-11', false, true),
('fte-4611686018581477679', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR BALS LT AVEIA 200ML', null, 'Klorane Bálsamo Após-Champô de Leite de Aveia respeita a integridade do couro cabeludo, restaurando o seu equilíbrio e conferindo suavidade e beleza ao cabelo. Deixa o cabelo suave graças à sua ação amaciadora e desembaraçadora. Textura fluida. Adequado a todos os tipos de cabelo.', 'Cabelo', 17.92, 15.36, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477679.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 34, '2026-11-11', false, true),
('fte-4611686018581479699', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR GELEIA AP CH PEONIA 150ML', null, 'Klorane Peónia Bálsamo após champô Calmante Bio apresenta uma textura fundente que amacia e ajuda a desembaraçar o cabelo. A Peónia acalma as irritações e o desconforto do couro cabeludo ao mesmo tempo que o hidrata e suaviza. O cabelo fica hidratado, suave e brilhante.', 'Cabelo', 18.48, 15.84, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479699.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 35, '2026-11-11', false, true),
('fte-4611686018581479564', 'farmacia-teixeira-guarda', 'DERCOS DENSI SOL BALS DENSIFICADOR 200ML', null, null, 'Cabelo', 25.31, 21.69, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479564.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 36, '2026-11-11', false, true),
('fte-4611686018581484206', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR BALS MANT CUPUAC BIO200ML', null, 'Klorane Manteiga de Cupuaçu Bálsamo após champô de nutrição e reparação Bio apresenta uma textura suave que ajuda a desembaraçar o cabelo. O Cupuaçu Bio possui propriedades nutritivas e é rico em ácidos gordos, que contribuem para um cabelo nutrido e reparado da raiz até às pontas. O cabelo fica brilhante, protegido e forte.', 'Cabelo', 17.08, 14.64, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484206.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 37, '2026-11-11', false, true),
('fte-4611686018581477637', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR BALS AP CH CAMOMILA 200ML', null, 'Klorane Bálsamo Camomila é um bálsamo à base de camomila, a qual é tradicionalmente utilizada para iluminar suavemente todos os tons de loiro. Graças à sua textura cremosa e fundente, este bálsamo após-champô repara, ilumina e desembaraça instantaneamente os cabelos loiros. O cabelo fica naturalmente carregado de luz e recupera brilho, suavidade e fica sedoso. Sem parabenos e silicones.', 'Cabelo', 16.97, 14.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477637.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 38, '2026-11-11', false, true),
('fte-4611686018581484299', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR FIGO INDIA SERUM 100ML', null, null, 'Cabelo', 26.82, 22.99, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484299.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 39, '2026-11-11', false, true),
('fte-4611686018581482493', 'farmacia-teixeira-guarda', 'DERCOS AMINEXIL CLINICAL MULH AMPX21', null, 'Vichy Dercos Clinical 5 mulher monodoses contém uma associação exclusiva de Aminexil, molécula antiqueda de referência com eficácia clinicamente comprovada, e 5 ativos, numa fórmula para uma ação completa. Os cabelos recuperam a resistência e a força. Textura levemente gelificada, não gordurosa, não cola e não oleosa. Não deixa resíduos visíveis. Fácil aplicação. Hipoalergénico. Testado dermatologicamente.', 'Cabelo', 71.62, 61.39, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482493.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 40, '2026-11-11', false, true),
('fte-4611686018581482394', 'farmacia-teixeira-guarda', 'URIAGE DS LOCAO 100ML', null, 'Uriage D.S. Lotion repara rapidamente o couro cabeludo agredido, deixando-o com um aspeto saudável e sem películas. Formulado com piroctona olamina, um ativo purificantee com atividade anti-fungíca. Esta loção reduz a descamação e melhora o aspeto da pele. Contém ainda glicerina, um agente protetor sobreengordurante que repõe parcialmente a gordura natural da pele retirada pela lavagem e manteiga de karité, que confere nutrição intensa. Sem perfume. Hipoalergénico, Não comedogénico.', 'Cabelo', 21.84, 18.72, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482394.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 41, '2026-11-11', false, true),
('fte-4611686018581484300', 'farmacia-teixeira-guarda', 'KLORANE CAPILAR FIGO INDIA MASCARA250ML', null, null, 'Cabelo', 27.33, 23.43, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484300.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 42, '2026-11-11', false, true),
('fte-4611686018581482608', 'farmacia-teixeira-guarda', 'VICHY HOMME STRUCTURE FORCE 50ML', null, 'Vichy Homme Structure Force Creme é composto por Ácido hialurónico, Silício, AHA e Água mineralizante de Vichy para um efeito hidratante suave e duradouro. Reestrutura e melhora a textura, firmeza e tonicidade da pele. Hipoalergénico. Testado sob controlo dermatológico e oftalmológico.', 'Homem', 34.94, 29.95, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482608.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 1, '2026-11-11', false, true),
('fte-4611686018581479603', 'farmacia-teixeira-guarda', 'LIERAC HOMME FL REDENSIF GLOBAL 50ML', null, null, 'Homem', 36.18, 31.01, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479603.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 2, '2026-11-11', false, true),
('fte-4611686018581479507', 'farmacia-teixeira-guarda', 'MARTIDERM ORIGIN FLASH SER 15ML', null, 'Martiderm The Originals Sérum Luminosidade Flash tem uma fórmula antifadiga imediata para recuperar a luminosidade, firmeza e uniformidade da pele. Efeito eliminador ótico das rugas e imperfeições para uma pele deslumbrante.', 'Homem', 26.60, 22.80, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479507.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 3, '2026-11-11', false, true),
('fte-4611686018581477326', 'farmacia-teixeira-guarda', 'LIERAC HOMME GEL DUCHE INTEG 200 ML', null, 'Lierac Homme Gel Douche Integral é um gel de duche transparente ultrafresco. Formulado com uma base lavante de origem vegetal, não dessecante, para uma limpeza suave e sem agressões. Com extratos de ginseng e de guaraná, com propriedades estimulantes e tonificantes, para uma ação energizante. Este cuidado de vitalidade 3 em 1, tonifica e refresca, em um só gesto, o rosto, o corpo e os cabelos. Limpa sem agredir a pele e os cabelos e aporta suavidade, energia e frescura. O resultado são uns cabelos limpos e brilhantes e uma pele limpa, suave, hidratada, fresca e estimulada. Sem sabão.', 'Homem', 10.58, 9.07, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477326.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 4, '2026-11-11', false, true),
('fte-4611686018581479602', 'farmacia-teixeira-guarda', 'LIERAC HOMME FL HIDRAT ENERG 50ML', null, null, 'Homem', 23.74, 20.35, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479602.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 5, '2026-11-11', false, true),
('fte-4611686018581477465', 'farmacia-teixeira-guarda', 'VICHY HOMME DEO ROLL ON PS 48H 50ML', null, 'Vichy Homme Desodorizante pele sensível regula a transpiração e diminui os desconfortos da pele durante 48 horas. Graças ao formato em roll-on, a aplicação torna-se fácil e rápida. Fresco e suave ao aplicar.', 'Homem', 14.22, 12.19, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477465.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 6, '2026-11-11', false, true),
('fte-4611686018581482531', 'farmacia-teixeira-guarda', 'VICHY HOMME DEO ROLL ON MANCHAS 50ML', null, 'Vichy Homme Desodorizante antimanchas 48h é indicado para homens que procuram um desodorizante ultrafresco de longa duração. Permite não só proteger a roupa das manchas indesejáveis, mas também a rigidez do tecido das camisas. Não deixa marcas brancas. Adequado à pele sensível. Sem álcool. Hipoalergénico. Testado dermatologicamente.', 'Homem', 14.67, 12.57, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581482531.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 7, '2026-11-11', false, true),
