('fte-4611686018581484278', 'farmacia-teixeira-guarda', 'LIERAC SUNISSIME LT SOL CRP SPF30 150ML', null, null, 'Solares', 31.08, 26.64, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484278.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 17, '2026-11-11', false, true),
('fte-4611686018581484279', 'farmacia-teixeira-guarda', 'LIERAC SUNISSIME LT SOL CRP SPF50 150ML', null, null, 'Solares', 31.08, 26.64, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484279.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 18, '2026-11-11', false, true),
('fte-4611686018581472859', 'farmacia-teixeira-guarda', 'ISDIN FOTOPROT HYDRO LOTION SPF50 200ML', null, 'Fotoprotetor Isdin Hydro Lotion Spf50 protege e desintoxica. A Chlorella Maris ajuda a desintoxicar e revitalizar a pele graças ao seu elevado teor de antioxidantes. Protetor bifásico, hidratante e de absorção rápida. Adequado para peles sensíveis. Resistente à água.', 'Solares', 30.69, 26.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472859.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 19, '2026-11-11', false, true),
('fte-4611686018581472830', 'farmacia-teixeira-guarda', 'ISDIN FOTOPROT LOCAO SPRAY SPF50 250ML', null, 'Isdin Fotoprotetor Isdin Loção Spray SPF 50 é um spray com fator de proteção solar elevado (SPF 50), especificamente desenvolvido para aplicação tanto na pele molhada como seca. A sua textura proporciona uma agradável sensação de frescura na pele, com uma absorção rápida e um toque final seco e sedoso. Adequado para pele atópica.', 'Solares', 32.14, 27.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472830.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 20, '2026-11-11', false, true),
('fte-4611686018581472816', 'farmacia-teixeira-guarda', 'ISDIN FOTOPROT TRP SPR WETSKIN 30 250ML', null, 'Fotoprotector ISDIN Transparent Spray Wet Skin SPF 30 é um protetor solar em spray, transparente e refrescante, especificamente desenvolvido para ser aplicado tanto em pele molhada como em pele seca. A tecnologia Wetflex®, permeável à água e permite a absorção na pele molhada sem deixar resíduo branco, mantendo o fator de proteção. Permite uma aplicação ótima em qualquer parte do corpo, incluindo as zonas de difícil acesso, graças à válvula que facilita uma difusão contínua, homogénea e em qualquer posição. Adequado para todos os tipos de pele.', 'Solares', 32.14, 27.55, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472816.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 21, '2026-11-11', false, true),
('fte-4611686018581472857', 'farmacia-teixeira-guarda', 'ISDIN FOTOPROT TRP SPR WETSKIN 50 250ML', null, 'Fotoprotetor Isdin Transparente Spray Wet Skin 50 fornece fotoproteção invisível e ligeira eficaz em pele molhada. Rápida absorção. Fórmula melhorada com Ginger Cell Protect, um extrato de gengibre 100% natural que, graças ao seu elevado conteúdo em antioxidantes, oferece proteção celular face ao dano oxidativo provocado pelo sol. A tecnología Wet Skin permite a sua absorção tanto em pele molhada como em pele seca, sem deixar resíduo branco e mantendo o fator de proteção. Resistente à água. Permite a aplicação em qualquer direção. Adaptado a todos os tipos de pele, incluindo peles sensíveis e/ou atópicas.', 'Solares', 32.70, 28.03, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472857.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 22, '2026-11-11', false, true),
('fte-4611686018581472806', 'farmacia-teixeira-guarda', 'ISDIN FOTOPROT HYDRO OIL SPF30 200ML', null, 'Isdin Fotoprotetor Isdin Hydro Oil SPF 30 é um óleo com fator de proteção solar elevado (SPF 30), para peles que necessitam de hidratação. Contém uma combinação de filtros e antioxidantes, que ajudam a evitar os danos cutâneos provocados por radiação solar, e Pro-Melanin Technology que estimula a produção de melanina, potenciando o bronzeado da pele. A sua textura confere uma agradável sensação de conforto e um acabamento seco e sedoso.', 'Solares', 30.69, 26.31, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472806.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 23, '2026-11-11', false, true),
('fte-4611686018581481025', 'farmacia-teixeira-guarda', 'AVENE SOLAR SPF50+ INTENSE PROT 150ML', null, 'Avène Solar Intense Protect Fluido ultrarresistente à água SPF50+ é um cuidado solar para pele sensível. Indicado para bebés, crianças e adultos. Contém um complexo antioxidante que protege as células contra o stress oxidativo. Graças à sua textura, deixa um acabamento seco e impercetível na pele.', 'Solares', 31.98, 27.41, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581481025.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 24, '2026-11-11', false, true),
('fte-4611686018581480974', 'farmacia-teixeira-guarda', 'URIAGE BARIESUN OLEO SECO SPF30 200ML', null, 'Uriage Bariésun Óleo Seco SPF 30 é formulado com um complexo filtrante, que assegura fotoestabilidade e uma cobertura alargada UVB-UVA. Hidrata intensamente a pele, graças à sua formulação enriquecida com Aquaspongines e Água Termal de Uriage. Contém vitaminas A C e E que neutralizam a ação dos radicais livre e previnem o envelhecimento precoce da pele. Apresenta uma textura agradável e não oleosa, suaviza a pele e ilumina o bronzeado. Está indicado em todos os tipos de pele, incluindo as mais sensíveis, e também pode ser usado no cabelo protegendo-o da secura e preservando a sua beleza natural. Hipoalergénico. Não comedogénico.', 'Solares', 27.55, 23.61, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581480974.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 25, '2026-11-11', false, true),
('fte-4611686018581472797', 'farmacia-teixeira-guarda', 'PIZ BUIN TAN PROT OLEO SPRAY SPF30 150ML', null, 'Piz Buin Tan & Protect Óleo Spray SPF 30 contém Illumitone, que ajuda a acelerar o processo natural do bronzeado da sua pele. O spray proporciona uma proteção eficaz contra os raios UVA/UVB. A fórmula de absorção hidrata a sua pele, ajuda a prevenir a descamação e contribui para um bronzeado mais duradouro. Não gorduroso e não pegajoso. Resistente à transpiração e à água.', 'Solares', 25.82, 22.13, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472797.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 26, '2026-11-11', false, true),
('fte-4611686018581480984', 'farmacia-teixeira-guarda', 'PIZ BUIN TAN PROT OLEO SPRAY SPF15 150ML', null, 'Piz Buin Tan & Protect Óleo Spray SPF 15 contém Illumitone, que ajuda a acelerar o processo natural do bronzeado da sua pele. O spray proporciona uma proteção eficaz contra os raios UVA/UVB. A fórmula de absorção hidrata a sua pele, ajuda a prevenir a descamação e contribui para um bronzeado mais duradouro. Não gorduroso e não pegajoso. Resistente à transpiração e à água.', 'Solares', 25.76, 22.08, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581480984.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 27, '2026-11-11', false, true),
('fte-4611686018581472815', 'farmacia-teixeira-guarda', 'ISDIN AFTER SUN LOCAO C/DOSEADOR 400ML', null, 'ISDIN Post-Solar Loção proporciona um efeito calmante e refrescante após a exposição solar graças aos seus ingredientes de Mentol e Camomila. Hidrata a pele irritada pela exposição solar e ajuda a reparar intensamente graças ao efeito dos seus ingredientes de Bisabolol, Mentol e Camomila. Evita a descamação da pele, prolongando o bronzeado.', 'Solares', 24.92, 21.36, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581472815.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 28, '2026-11-11', false, true),
('fte-4611686018581484120', 'farmacia-teixeira-guarda', 'PIZ BUIN AFT SUN LOC INT BRONZ200ML DUO', null, null, 'Solares', 26.43, 22.65, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581484120.png', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 29, '2026-11-11', false, true),
('fte-4611686018581481001', 'farmacia-teixeira-guarda', 'PIZ BUIN AFT SUN ALIV INST BRUMA SPR 200ML', null, 'Piz Buin After Sun Bruma Express Alívio Imediato com ácido hialurónico, proporciona 48h de hidratação e ajuda a prevenir a descamação, para um bronzeado mais duradouro. Textura ultraligeira, de absorção imediata. Fórmula não gordurosa e não pegajosa.', 'Solares', 21.17, 18.15, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581481001.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 30, '2026-11-11', false, true),
('fte-4611686018581479489', 'farmacia-teixeira-guarda', 'PIZ BUIN AFT SUN PCK LOC SUA REF200MLX2', null, null, 'Solares', 26.43, 22.65, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581479489.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 31, '2026-11-11', false, true),
