('fte-4611686018581477177', 'farmacia-teixeira-guarda', 'CAUDALIE VINOSUN AGUA SOL SPF50+150ML', null, null, 'Solares', 30.13, 25.83, 'https://ojykpzwqrtusfeakzrna.supabase.co/storage/v1/object/public/product-images/farmacias/farmacia-teixeira-guarda/fte-4611686018581477177.jpg', true, 'glovo-provisorio-2026-11-11', 'glovo', false, false, 33, '2026-11-11', false, true),
